// Isolated design prototype. No camera, media decoding, network or deferred business logic.
const $=s=>document.querySelector(s),stage=$('#stage');
const names=['GAIA','PANDEMIC','RE-BIRTH','WHITE-GUARDIAN','CONSCIENCE','SANCTUARY'];
const colors=['#31d7f2','#b29a82','#d8a9c1','#bfe9ff','#ff6a2a','#f3b95f'];
const images=['gaia','pandemic','rebirth','guardian','conscience','sanctuary'];
let state={concept:'A',locale:'en',view:'home',performer:0,phase:'focus',gesture:'off',overlay:null};let opener=null,animationTimer=null,closeTimer=null,overlayGeneration=0;
const T=(en,zh)=>state.locale==='zh'?zh:en;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const img=(i,cls='art')=>`<img class="${cls}" src="assets/${images[i]}.png" alt="${names[i]} · ${T('existing performer artwork','既有表演者作品')}">`;
function header(tag){return `<header class="app-header"><div><p class="wordmark">AWAKENING CELEBRATIONS</p><p class="eyebrow">${tag}</p></div><button class="language" data-action="language" aria-label="${T('Switch to Traditional Chinese','切換至英文')}">English / 繁體中文</button></header>`;}
function shell(){if(['activation','prepare','playing','completed'].includes(state.phase)&&state.view==='focus')return `<footer class="shell reduced"><span class="brand">${names[state.performer]}</span><p>${T('Settings & AI after this moment','此段落結束後可開啟設定與 AI')}</p><button data-action="leave">${T('Leave portrait · Esc','離開畫像・Esc')}</button></footer>`;return `<footer class="shell"><span class="brand">VER.KA</span><span class="capture">${T('Camera off · Design preview','相機已關閉・設計預覽')}</span>${['settings','ai','help','privacy'].map((a,i)=>`<button id="shell-${a}" data-action="${a}">${[T('Settings','設定'),T('Ask AI','詢問 AI'),T('Help','說明'),T('Privacy','隱私')][i]}</button>`).join('')}</footer>`;}
function home(){return img(5,'home-art art')+header(T('AN INTERACTIVE EXHIBITION','互動展演體驗'))+`<section class="home-content"><h1 class="title">${T('A presence.<br>An awakening.','與存在相遇。<br>讓感知甦醒。')}</h1><p class="lede">${T('Six performers. A world revealed through your movement.','六位表演者，以你的動作，開啟感知世界。')}</p><p class="privacy-note">${T('Your camera stays off until you choose gesture interaction.','相機會保持關閉，直到你選擇手勢互動。')}</p><button class="primary" data-action="privacy">${T('Review & begin','閱讀並開始')}</button><p class="status-inline">${T('Your choice, this session only.','你的選擇，僅限本次體驗。')}</p></section>`;}
function selection(){return header(T('COLOR RELEASE','色彩釋放'))+`<section class="content"><h1 class="title">${T('Who will you awaken?','你想喚醒哪種存在？')}</h1><p class="lede">${T('Point to explore. Make a fist to choose. Or click / press 1–6.','指向以探索，握拳以選擇。也可點擊或按 1–6。')}</p><div class="performers">${names.map((n,i)=>`<button class="performer ${state.gesture==='target'&&i===state.performer?'targeted':''}" style="--performer:${colors[i]}" data-performer="${i}" data-targetlabel="${T('Targeted · not yet selected','已指向・尚未選取')}">${img(i)}<span class="name">${n}</span><span class="number">0${i+1} / ${T('Choose','選擇')}</span></button>`).join('')}</div>${img(state.performer,'spatial-art')}</section>`;}
function cinematic(){const phases={focus:T('Focus','凝視'),activation:T('Activation','啟動'),prepare:T('Preparing Living Portrait','正在準備流動畫像'),playing:T('Living Portrait','流動畫像'),completed:T('Completion event received','已收到播放完成事件'),release:T('Release','釋放')};return img(state.performer,'cinema-art')+`<section class="cinema-label"><h1>${names[state.performer]}</h1><p>${phases[state.phase]}</p></section>${state.phase==='focus'?`<div class="cinema-action"><p>${T('Show both open palms, or use the play action.','張開雙手，或使用播放操作。')}</p><button class="primary" data-action="activate">${T('Preview activation','預覽啟動動態')}</button></div>`:state.phase==='prepare'?`<div class="cinema-action"><p>${T('Preparing… The artwork remains until the first decoded frame.','準備中…第一個解碼影格出現前，保留原作品。')}</p></div>`:state.phase==='release'?`<div class="cinema-action"><p>${T('A moment to return.','回到此刻。')}</p><button class="primary" data-action="selection">${T('Return to the experience','返回體驗')}</button><button class="secondary" data-action="ai">${T('Ask about this presence','詢問此刻的存在')}</button></div>`:''}`;}
function components(){return header(T('COMPONENT / STATE STUDY','元件／狀態研究'))+`<section class="content components"><h1 class="title">${T('One language of interaction.','一致的互動語言。')}</h1><div class="spec-grid"><article class="spec-box"><h3>${T('Control states','控制項狀態')}</h3><div class="examples"><button class="primary">${T('Default','預設')}</button><button class="example">${T('Hover','游標停留')}</button><button class="example is-pressed">${T('Pressed','按下')}</button><button class="example is-focused">${T('Focus','焦點')}</button><button class="example" disabled>${T('Unavailable','目前無法使用')}</button><button class="example is-deferred" disabled>${T('After this moment','此段落結束後')}</button></div></article><article class="spec-box"><h3>${T('Gesture feedback','手勢回饋')}</h3><p>${T('Ready → pointing → target acquired → fist confirmed. Tracking loss cancels acquisition.','就緒 → 指向 → 鎖定目標 → 握拳確認。失去追蹤時取消目標取得。')}</p><span class="pill">${T('Visual events only','僅為視覺事件')}</span></article><article class="spec-box"><h3>${T('Readable materials','可讀的材質')}</h3><p>${T('Quiet chrome, floating panels, opaque reading areas. Reduced effects retain hierarchy.','安靜的導覽、浮動面板、不透明閱讀區。降低效果仍保有層次。')}</p><p>${T('Background blur here is a browser approximation.','此處的背景模糊僅為瀏覽器近似效果。')}</p></article><article class="spec-box"><h3>${T('Assistant states','助理狀態')}</h3><p>${T('Empty · composing · waiting · reply · network error · unexpected response · retry · cancelled.','空白・輸入中・等待・回覆・網路錯誤・回覆異常・重試・已取消。')}</p></article><article class="spec-box"><h3>${T('Camera states','相機狀態')}</h3><p>${T('Off · suspended · starting · ready · no hand · tracking lost · device error.','關閉・暫停擷取・啟動中・就緒・未偵測到手部・失去追蹤・裝置錯誤。')}</p></article><article class="spec-box"><h3>${T('Unavailable vs deferred','無法使用與暫緩開啟')}</h3><p>${T('Unavailable explains a missing capability. Deferred explains a safe boundary and offers explicit Open later.','無法使用會說明缺少的功能。暫緩開啟會說明安全邊界，並於稍後提供開啟操作。')}</p></article></div></section>`;}
const deferred=[['Sound','聲音','Volume, mute, output unavailable, applying, failed.','音量、靜音、輸出無法使用、套用中、失敗。'],['Accessibility','無障礙','Reduced motion, reduced effects, readable text. No preference is applied here.','減少動態效果、降低視覺效果、易讀文字。此處不套用偏好。'],['Tracking & camera','追蹤與相機','Permission, capture and preview remain separate.','權限、擷取與預覽分別呈現。'],['End / restart','結束／重新開始','Confirm destination and reset scope. Cancel keeps your experience.','先確認目的地與重設範圍。取消會保留體驗。'],['Contextual Help','情境說明','Input help and return to opener. Combine redundant Guide.','提供操作說明並返回原處，整合重複的指南。'],['Calibration · conditional','校正・條件式','Only if measured alignment needs justify it. No success is simulated.','僅在量測證實需要校正時納入。不模擬成功結果。'],['Souvenir · conditional','紀念留存・條件式','Approved takeaway, destination, expiry and privacy first. No QR is generated.','先核准留存內容、目的地、期限與隱私規則。不產生 QR 碼。']];
function deferredView(){return header(T('COMPLETE PRODUCT / DEFERRED','完整產品／暫緩功能'))+`<section class="content deferred"><h1 class="title">${T('Designed together. Built later.','一併設計，分階段實現。')}</h1><div class="spec-grid">${deferred.map((d,i)=>`<article class="spec-box"><h3>${T(d[0],d[1])}</h3><p>${T(d[2],d[3])}</p><span class="pill">${T('Design only · functionality deferred','僅設計・功能暫緩')}</span>${i===5?`<button class="quiet" data-action="calibration">${T('View optional layout','查看選用版面')}</button>`:i===6?`<button class="quiet" data-action="souvenir">${T('View optional layout','查看選用版面')}</button>`:''}</article>`).join('')}</div></section>`;}
function render(){clearTimeout(animationTimer);clearTimeout(closeTimer);overlayGeneration++;stage.className=`concept-${state.concept} ${state.locale==='zh'?'zh':''} ${state.view} ${state.phase} enter ${$('#reduce').checked?'review-reduced':''} ${$('#opaque').checked?'review-opaque':''}`;stage.lang=state.locale==='zh'?'zh-Hant':'en';stage.innerHTML=(state.view==='home'?home():state.view==='selection'?selection():state.view==='focus'?cinematic():state.view==='components'?components():state.view==='deferred'?deferredView():home())+shell()+gesture();$('#view').value=state.view;document.documentElement.lang=stage.lang;if(state.overlay)openOverlay(state.overlay,false);}
function gesture(){if(state.gesture==='off'||!['selection','focus'].includes(state.view))return '';const copy={ready:T('Gesture ready · point to explore','手勢就緒・指向以探索'),lost:T('Tracking lost · show your hand, or click to continue','失去追蹤・請將手伸到相機前，或點擊繼續'),target:T('Target acquired · make a fist to confirm','已鎖定目標・握拳以確認'),confirmed:T('Confirmed · '+names[state.performer],'已確認・'+names[state.performer])};return `<div class="gesture-indicator" data-state="${state.gesture}">${copy[state.gesture]}<small> · ${T('illustration','示意')}</small></div>`;}
function navigate(v){state.overlay=null;state.view=v;state.phase='focus';render();}
function row(en,zh,detail,button,disabled=true){return `<div class="settings-row"><div><strong>${T(en,zh)}</strong><p>${detail}</p></div><button ${disabled?'disabled':''} ${en==='Language'?'data-action="language"':''}>${button}</button></div>`;}
function panelContent(type){if(type==='settings')return `<h2>${T('Your experience','你的體驗')}</h2><p class="sub">${T('Quiet controls. Return to exactly where you were.','安靜調整，回到剛才的體驗。')}</p><div class="settings-grid">${row('Language','語言','English / 繁體中文',T('Switch','切換'),false)}${row('Sound','聲音',T('Volume & mute · function deferred','音量與靜音・功能暫緩'),T('Deferred','暫緩'))}${row('Accessibility','無障礙',T('Motion, effects and text · function deferred','動態、視覺效果與文字・功能暫緩'),T('Deferred','暫緩'))}${row('Camera & privacy','相機與隱私',T('Capture is off in this design preview','設計預覽未啟動擷取'),T('Off','關閉'))}${row('End experience','結束體驗',T('Reset policy requires approval','重設規則待核准'),T('Deferred','暫緩'))}</div><p class="deferred-copy">${T('Optional calibration is available through Help only if a real alignment need is established.','校正僅在確認有實際對位需求時，由說明入口提供。')}</p>`;
 if(type==='ai')return `<h2>${T('A different perspective','從另一個角度，看見')}</h2><p class="sub">${names[state.performer]} / ${T('Assistant · camera not required','AI 助理・不需開啟相機')}</p><div class="suggestions">${[T('Meet '+names[state.performer],'認識 '+names[state.performer]),T('About this experience','關於這段體驗'),T('How to interact','如何互動')].map(t=>`<button disabled>${t}</button>`).join('')}</div><p class="conversation-empty">${T('Your conversation begins here.','從這裡開始對話。')}</p><p class="deferred-copy">${T('Layout specimen. No message is sent and no assistant reply is fabricated.','版面示例。不會傳送訊息，也不會模擬助理回覆。')}</p><div class="question-field"><input aria-label="${T('Question layout specimen','問題欄位版面示例')}" disabled placeholder="${T('Ask a question…','輸入問題…')}"><button disabled>${T('Ask','詢問')}</button></div>`;
 if(type==='privacy')return `<h2>${T('Your presence. Your choice.','你的參與，由你選擇。')}</h2><p class="sub">${T('Camera interaction starts only after your explicit session consent. Preview visibility is a separate choice.','相機互動僅在你明確同意本次體驗後啟動。預覽是否顯示是另一項選擇。')}</p><p class="warning">${T('Final camera and AI data-handling copy needs product approval. This prototype does not request permission or activate hardware.','相機與 AI 資料處理說明仍待產品核准。此預覽不請求權限，也不啟動硬體。')}</p><div class="panel-footer"><button class="primary" data-action="selection">${T('Explore the design preview','探索設計預覽')}</button></div>`;
 if(type==='help')return `<h2>${T('Move at your own pace.','以自己的步調探索。')}</h2><p class="sub">${T('Point, then make a fist to select. Show both palms to begin a portrait. Hold one open palm to request Back.','指向後握拳選擇。張開雙手以開始畫像。張開單手並保持以請求返回。')}</p><p class="sub">${T('Pointer and keyboard remain alternatives. Global gesture activation is not currently established.','亦可使用滑鼠與鍵盤。全域手勢啟動尚未建立。')}</p><button class="secondary" data-action="calibration">${T('Optional alignment help','選用對位說明')}</button>`;
 if(type==='calibration')return `<h2>${T('Alignment, only if needed.','僅在需要時，調整對位。')}</h2><p class="sub">${T('Optional flow: explain → check device → acquire target → evaluate → retry or cancel.','選用流程：說明 → 檢查裝置 → 取得目標 → 評估 → 重試或取消。')}</p><p class="warning">${T('No calibration algorithm or success result is simulated. Keep this out of primary navigation until a measured need exists.','此處不模擬校正演算法或成功結果。在量測證實需要之前，不放入主要導覽。')}</p><button class="secondary" disabled>${T('Calibration not available','校正目前無法使用')}</button>`;
 if(type==='souvenir')return `<h2>${T('Carry a moment with you.','帶走此刻的感受。')}</h2>${img(state.performer,'optional-art')}<p class="sub">${T('A takeaway is optional. Its content, destination, expiry and privacy rules must be approved first.','紀念留存為選用功能。須先核准內容、目的地、期限與隱私規則。')}</p><div class="no-qr">${T('Delivery unavailable · no QR code','留存服務未提供・沒有 QR 碼')}</div><p class="deferred-copy">${T('Ready, expired, offline and error layouts are specified in DeferredFeatureUX.md.','已就緒、已過期、離線與錯誤版面規格見 DeferredFeatureUX.md。')}</p>`;
 return '';}
function openOverlay(type,remember=true){clearTimeout(closeTimer);overlayGeneration++;if(remember)opener=document.activeElement;state.overlay=type;document.querySelector('.modal-backdrop')?.remove();const outer=document.createElement('div');outer.className='modal-backdrop';outer.innerHTML=`<section class="panel" role="dialog" aria-modal="true" aria-label="${T(type+' design panel',type+' 設計面板')}"><button class="panel-close" data-action="close" aria-label="${T('Close panel','關閉面板')}">${T('Close · Esc','關閉・Esc')}</button>${panelContent(type)}</section>`;stage.append(outer);for(const n of stage.children)if(n!==outer)n.inert=true;outer.querySelector('button:not(:disabled)')?.focus();}
function closeOverlay(){const overlay=$('.modal-backdrop');if(!overlay||overlay.classList.contains('leaving'))return;const closingGeneration=++overlayGeneration;const target=opener;const key=target?.id;state.overlay=null;overlay.classList.add('leaving');const finish=()=>{if(closingGeneration!==overlayGeneration)return;overlay.remove();for(const n of stage.children)n.inert=false;if(target?.isConnected)target.focus();else if(key)document.getElementById(key)?.focus();else $('#shell-settings')?.focus();};if($('#reduce').checked)finish();else closeTimer=setTimeout(finish,160);}
function activate(){state.overlay=null;state.view='focus';state.phase='activation';render();$('.cinema-art').classList.add('activation-glow');$('#event-log').textContent=T('Presentation only: 650ms fade / 3s activation. Use “preparing” next; no video is started.','僅呈現動態：650 毫秒淡入淡出／3 秒啟動。接著使用「準備中」；不會啟動影片。');}
stage.addEventListener('click',e=>{const card=e.target.closest('[data-performer]');if(card&&!state.overlay){state.performer=+card.dataset.performer;state.gesture='off';navigate('focus');return;}const a=e.target.closest('[data-action]')?.dataset.action;if(!a)return;if(a==='close')return closeOverlay();if(a==='language'){const current=state.overlay;state.locale=state.locale==='en'?'zh':'en';$('#locale').value=state.locale;render();if(current)state.overlay=current;return;}if(a==='selection')return navigate('selection');if(a==='activate')return activate();if(a==='leave'){state.phase='release';render();return;}openOverlay(a);});
document.addEventListener('keydown',e=>{if(state.overlay||document.querySelector('.modal-backdrop')){if(e.key==='Escape'){e.preventDefault();closeOverlay();return;}if(e.key==='Tab'){const nodes=[...$('.panel').querySelectorAll('button:not(:disabled),input:not(:disabled),[tabindex="0"]')];const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}return;}if(e.target.matches('input,select,textarea'))return;if(e.key==='Escape'&&state.view==='focus'){e.preventDefault();state.phase='release';render();}if(state.view==='selection'&&/^[1-6]$/.test(e.key)){state.performer=+e.key-1;state.gesture='off';navigate('focus');}});
for(const id of ['concept','view','locale','reduce','opaque'])$('#'+id).addEventListener('change',()=>{state.concept=$('#concept').value;state.locale=$('#locale').value;const v=$('#view').value;state.overlay=null;state.phase='focus';if(v==='settings'||v==='ai'){state.view='selection';render();openOverlay(v);$('#view').value=v;}else{state.view=v;render();}});
document.querySelector('.lab-actions').addEventListener('click',e=>{const ev=e.target.closest('[data-event]')?.dataset.event;if(!ev)return;state.overlay=null;if(ev==='entrance'){render();return;}if(['ready','lost','target'].includes(ev)){state.view='selection';state.gesture=ev;render();}if(ev==='confirm'){state.gesture='confirmed';state.view='focus';state.phase='focus';render();}if(ev==='activate')activate();if(['prepare','frame','complete','cancel'].includes(ev)){state.view='focus';state.phase={prepare:'prepare',frame:'playing',complete:'release',cancel:'release'}[ev];render();}$('#event-log').textContent=T('Review event: ','檢視事件：')+ev+T(' · illustration only; no detector, video callback or business outcome was executed.','・僅為示意，未執行偵測器、影片回呼或功能結果。');});
render();
